<?php
require_once __DIR__.'/includes/learning-tools.php';learn_ensure_tables();$today=date('Y-m-d');$questions=[['¿Qué palabra es un saludo?',['Hola','Baño','Ayer','Cansado'],'Hola'],['¿Qué palabra expresa cortesía?',['Gracias','Escuela','¿Quién?','Venir'],'Gracias'],['¿Cuál es un número?',['Ocho','Familia','Aprender','Oyente'],'Ocho'],['¿Cuál pregunta por un lugar?',['¿Dónde?','¿Cuándo?','¿Cómo?','¿Qué?'],'¿Dónde?'],['¿Cuál es una acción?',['Ayudar','Triste','Nombre','Buenas noches'],'Ayudar']];$challenge=['title'=>'Cinco pasos de hoy','description'=>'Responde cinco preguntas mixtas del material estudiado.','xp_reward'=>20];$already=false;$prior=null;try{$q=learn_db()->prepare('SELECT * FROM daily_challenges WHERE challenge_date=?');$q->execute([$today]);$dbrow=$q->fetch();if($dbrow){$challenge['title']=$dbrow['title'];$challenge['description']=$dbrow['description']?:$challenge['description'];$challenge['xp_reward']=(int)$dbrow['xp_reward'];if($dbrow['content_json']){$parsed=json_decode($dbrow['content_json'],true);if(is_array($parsed)&&count($parsed))$questions=$parsed;}}$q=learn_db()->prepare('SELECT * FROM daily_challenge_progress WHERE challenge_date=? AND user_id=?');$q->execute([$today,$learnUserId]);$prior=$q->fetch();$already=$prior&&!empty($prior['completed']);}catch(Throwable $e){error_log('[daily challenge] '.$e->getMessage());}
if($_SERVER['REQUEST_METHOD']==='POST'){learn_verify_csrf();if($already){header('Location: challenge.php?done=1');exit;}$wasCompleted=$already;$answers=$_POST['answer']??[];$score=0;foreach($questions as $i=>$q)if(($answers[$i]??'')===($q['answer']??$q[2]??''))$score++;$completed=$score>=ceil(count($questions)*.8)?1:0;try{$q=learn_db()->prepare('INSERT INTO daily_challenge_progress(challenge_date,user_id,score,completed,completed_at) VALUES(?,?,?,?,IF(?,NOW(),NULL)) ON DUPLICATE KEY UPDATE score=GREATEST(score,VALUES(score)),completed=GREATEST(completed,VALUES(completed)),completed_at=IF(VALUES(completed)=1,NOW(),completed_at)');$q->execute([$today,$learnUserId,$score,$completed,$completed]);}catch(Throwable $e){error_log('[challenge save] '.$e->getMessage());}$prior=['score'=>$score,'completed'=>$completed];$already=(bool)$completed;$awarded=0;if($completed && !$wasCompleted){ /* completion state was absent before this submission */ $awarded=(int)$challenge['xp_reward']; learn_record_practice($learnUserId,$awarded); }$_SESSION['challenge_result']=['score'=>$score,'total'=>count($questions),'completed'=>$completed,'xp'=>$awarded];header('Location: challenge.php?result=1');exit;}
learn_header('Desafío diario',$today.' · '.$challenge['description']);if(isset($_GET['result'])&&isset($_SESSION['challenge_result'])){$r=$_SESSION['challenge_result'];echo '<section class="learn-panel"><div class="learn-result-score">'.(int)$r['score'].'/'.(int)$r['total'].'</div><h2>'.($r['completed']?'¡Desafío completado!':'Buen intento').'</h2><p class="learn-muted">'.($r['completed']?'Has superado el reto de hoy. Recompensa prevista: '.(int)$challenge['xp_reward'].' XP.':'Necesitas al menos 80% para completarlo. Puedes intentarlo otra vez hoy.').'</p><a class="learn-button" href="challenge.php">Volver al desafío</a></section>';unset($_SESSION['challenge_result']);}elseif($already){echo '<section class="learn-panel"><span class="learn-badge">✓ COMPLETADO HOY</span><h2>¡Reto cumplido!</h2><p class="learn-muted">Resultado guardado: '.(int)$prior['score'].' aciertos. Vuelve mañana para un nuevo reto.</p></section>';}else{echo '<section class="learn-panel"><span class="learn-badge">RETO DIARIO · +'.(int)$challenge['xp_reward'].' XP PREVISTOS</span><h2>'.learn_h($challenge['title']).'</h2><form method="post" class="learn-form">'.learn_csrf();foreach($questions as $i=>$q){$prompt=$q['prompt']??$q[0]??'Pregunta';$opts=$q['options']??$q[1]??[];echo '<fieldset class="learn-question"><legend>'.($i+1).'. '.learn_h($prompt).'</legend><div class="learn-options">';foreach($opts as $o)echo '<label class="learn-option"><input type="radio" name="answer['.$i.']" value="'.learn_h($o).'" required>'.learn_h($o).'</label>';echo '</div></fieldset>'; }echo '<button class="learn-button">Enviar desafío →</button></form></section>'; }learn_footer();
